<div class="container"><div class="row justify-content-center"><div class="col-lg-7"><div class="page-heading"><span class="section-kicker">Pelacakan pengajuan</span><h1><?= $tracking ? 'Status pengajuan' : 'Kode tidak ditemukan' ?></h1></div><?php if ($tracking): ?><section class="data-panel mb-4"><div class="d-flex justify-content-between flex-wrap gap-3"><div><span class="text-secondary small">Jenis surat</span><h2 class="h5 mt-1"><?= e($tracking['type_name']) ?></h2></div><div><span class="text-secondary small">Status saat ini</span><div class="mt-1"><span class="status-pill pending"><?= e(status_label($tracking['status'])) ?></span></div></div></div><p class="small text-secondary mt-3 mb-0">Pengajuan masuk <?= e(date('d/m/Y', strtotime($tracking['created_at']))) ?>. Detail identitas hanya tersedia setelah masuk ke akun warga.</p></section><section class="data-panel"><h2 class="h6 mb-4">Perjalanan pengajuan</h2><div class="timeline"><?php foreach ($history as $item): ?><div class="timeline-item"><strong><?= e(status_label($item['new_status'])) ?></strong><small><?= e(date('d/m/Y H:i', strtotime($item['created_at']))) ?></small></div><?php endforeach; ?></div></section><?php else: ?><a class="btn btn-outline-success" href="/cek-status">Coba lagi</a><?php endif; ?></div></div></div>